package br.com.sussmartcare.triage.infrastructure.eventsourcing;
import br.com.sussmartcare.triage.domain.*; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class EventSourcedTriageRepository implements TriageRepository {private final TriageStoredEventRepository events;private final ObjectMapper mapper;public EventSourcedTriageRepository(TriageStoredEventRepository e,ObjectMapper m){events=e;mapper=m;}
 public Triage save(Triage t){var changes=t.pullChanges();long version=t.getVersion()-changes.size()+1;for(var change:changes)events.save(new TriageStoredEvent(t.getId(),version++,change.getClass().getSimpleName(),json(change),change.occurredAt()));return t;}
 public Optional<Triage> findById(UUID id){var stored=events.findByStreamIdOrderByEventVersionAsc(id);if(stored.isEmpty())return Optional.empty();return Optional.of(Triage.rehydrate(stored.stream().map(this::decode).toList()));}
 public Optional<Triage> findByVisitId(UUID visitId){return events.findByEventTypeOrderByOccurredAtDesc("TriageStarted").stream().map(this::decode).filter(e->e instanceof TriageDomainEvent.TriageStarted x&&x.visitId().equals(visitId)).findFirst().map(e->((TriageDomainEvent.TriageStarted)e).triageId()).flatMap(this::findById);}
 private String json(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}} private TriageDomainEvent decode(TriageStoredEvent e){try{return switch(e.getEventType()){case "TriageStarted"->mapper.readValue(e.getPayload(),TriageDomainEvent.TriageStarted.class);case "TriageAssessed"->mapper.readValue(e.getPayload(),TriageDomainEvent.TriageAssessed.class);case "ClinicalPriorityConfirmed"->mapper.readValue(e.getPayload(),TriageDomainEvent.ClinicalPriorityConfirmed.class);default->throw new IllegalStateException("Evento de triagem desconhecido: "+e.getEventType());};}catch(Exception ex){throw new IllegalStateException("Falha reidratando triagem",ex);}}
}
